payload.text:
Here is the updated code to include the History functionality, allowing users to save and review past food analyses.

I have:
1.  **Updated `types.ts`**: Added `HistoryItem` interface and `AppView.HISTORY`.
2.  **Updated `App.tsx`**:
    *   Implemented persistent storage using `localStorage` (saving the last 50 analyses).
    *   Added a "Historial" button in the navigation bar.
    *   Created a new History View with a clean, list-based design showing date, time, and calorie summary.
    *   Handled displaying analysis details from history (with a placeholder for images since we don't store large image files to save space).

# Updated files:

## types.ts

Add `HistoryItem` interface and `HISTORY` to `AppView` enum.

```typescript
export interface Recipe {
  name: string;
  description: string;
  calories: number;
  ingredients: string[];
  instructions: string[];
}

export interface MacroData {
  protein: number;
  carbs: number;
  fat: number;
}

export interface NutritionAnalysis {
  calories: number;
  macros: MacroData;
  ingredients: string[];
  healthySwaps: string[];
  healthierRecipes: Recipe[];
}

export interface HistoryItem {
  id: string;
  timestamp: number;
  analysis: NutritionAnalysis;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

export enum AppView {
  HOME = 'HOME',
  ANALYSIS = 'ANALYSIS',
  HISTORY = 'HISTORY',
}
```

## App.tsx

Implement history state management, saving logic, and the History UI view.

```tsx
import React, { useState, useEffect } from 'react';
import { analyzeFoodImage, getQuickTip } from './services/geminiService';
import { NutritionAnalysis, AppView, Recipe, HistoryItem } from './types';
import MacrosChart from './components/PieChart';
import ChatBot from './components/ChatBot';

function App() {
  const [view, setView] = useState<AppView>(AppView.HOME);
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<NutritionAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [quickTip, setQuickTip] = useState<string>('');
  const [selectedRecipe, setSelectedRecipe] = useState<Recipe | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);

  useEffect(() => {
    // Load a quick tip on mount using the Lite model
    getQuickTip().then(setQuickTip);

    // Load history from local storage
    const savedHistory = localStorage.getItem('snapcal_history');
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }
  }, []);

  const saveToHistory = (newAnalysis: NutritionAnalysis) => {
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      analysis: newAnalysis,
    };

    // Keep only last 50 items to avoid localStorage limits
    const updatedHistory = [newItem, ...history].slice(0, 50);
    setHistory(updatedHistory);
    localStorage.setItem('snapcal_history', JSON.stringify(updatedHistory));
  };

  const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      const file = event.target.files[0];
      const reader = new FileReader();

      reader.onloadend = async () => {
        const base64String = reader.result as string;
        // Strip prefix for Gemini API if present (data:image/jpeg;base64,)
        const base64Data = base64String.split(',')[1];

        setImageSrc(base64String);
        setView(AppView.ANALYSIS);
        setLoading(true);
        setError(null);

        try {
          const result = await analyzeFoodImage(base64Data);
          setAnalysis(result);
          saveToHistory(result);
        } catch (err) {
          setError("No pudimos analizar la imagen. Intenta con una foto más clara.");
        } finally {
          setLoading(false);
        }
      };

      reader.readAsDataURL(file);
    }
  };

  const resetApp = () => {
    setView(AppView.HOME);
    setImageSrc(null);
    setAnalysis(null);
    setError(null);
    setSelectedRecipe(null);
  };

  const loadHistoryItem = (item: HistoryItem) => {
    setAnalysis(item.analysis);
    setImageSrc(null); // Images are not stored in history to save space
    setView(AppView.ANALYSIS);
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString('es-ES', {
      day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
    });
  };

  return (
    <div className="min-h-screen bg-[#FDFDFD] text-gray-900 font-sans selection:bg-indigo-100 pb-20 md:pb-0 relative overflow-x-hidden">

      {/* Dynamic Ambient Background */}
      <div className="fixed inset-0 z-0 pointer-events-none overflow-hidden">
          <div className="absolute -top-[20%] -left-[10%] w-[70%] h-[70%] rounded-full bg-blue-100/40 blur-[120px] animate-pulse"></div>
          <div className="absolute top-[40%] -right-[20%] w-[60%] h-[60%] rounded-full bg-purple-100/40 blur-[120px] animate-pulse" style={{animationDelay: '2s'}}></div>
      </div>

      {/* Top Navigation */}
      <nav className="sticky top-0 z-40 bg-white/70 backdrop-blur-xl border-b border-gray-100/50 px-6 py-4 flex justify-between items-center transition-all duration-300">
        <div className="flex items-center gap-2 cursor-pointer group" onClick={resetApp}>
          <div className="w-9 h-9 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-blue-500/20 group-hover:scale-105 transition-transform">S</div>
          <span className="font-bold text-xl tracking-tight text-gray-900">SnapCal</span>
        </div>

        <div className="flex items-center gap-3">
             <button 
                onClick={() => setView(AppView.HISTORY)}
                className={`p-2 rounded-full transition-colors ${view === AppView.HISTORY ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-gray-100 text-gray-500'}`}
                title="Historial"
             >
                 <span className="material-icons-round">history</span>
             </button>
             <div className="flex items-center gap-2 text-[10px] font-bold tracking-wider uppercase text-emerald-600 bg-emerald-50/80 backdrop-blur-sm border border-emerald-100 px-3 py-1.5 rounded-full shadow-sm hidden sm:flex">
                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
                Online
            </div>
        </div>
      </nav>

      <main className="relative z-10 max-w-md mx-auto w-full pt-6 px-5 md:max-w-2xl">

        {view === AppView.HOME && (
          <div className="flex flex-col items-center pt-6 md:pt-12 space-y-10 animate-fade-in-up">

            {/* Hero Section */}
            <div className="text-center space-y-6 relative">

               {/* Decorative glow behind text */}
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 bg-gradient-to-r from-blue-400 to-indigo-400 rounded-full blur-[80px] opacity-20 -z-10"></div>

               {/* Badge */}
               <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white border border-gray-200/60 shadow-sm mb-2 backdrop-blur-md">
                  <span className="text-xs font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-purple-600 tracking-wide uppercase">
                    ✨ Potenciado por Gemini 2.5
                  </span>
               </div>

              <h1 className="text-5xl md:text-7xl font-black text-gray-900 tracking-tighter leading-[1.05] drop-shadow-sm">
                Tu Comida,<br />
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600">
                  Decodificada.
                </span>
              </h1>

              <p className="text-lg text-gray-500 font-medium max-w-xs mx-auto md:max-w-lg leading-relaxed">
                Transforma cualquier foto en un plan nutricional preciso y recetas saludables al instante.
              </p>

              {quickTip && (
                <div className="inline-block mt-4 px-4 py-2 bg-indigo-50/80 backdrop-blur-sm border border-indigo-100 text-indigo-700 text-xs rounded-xl font-medium">
                  💡 Tip del día: {quickTip}
                </div>
               )}
            </div>

            {/* Main Action Card */}
            <div className="w-full max-w-sm relative group">
                {/* Glow Effect */}
                <div className="absolute -inset-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500 rounded-[2.5rem] blur-xl opacity-20 group-hover:opacity-40 transition duration-500 group-hover:duration-200"></div>

                <label className="relative flex flex-col items-center justify-center w-full aspect-[4/5] md:aspect-square bg-white border border-gray-100 rounded-[2rem] cursor-pointer shadow-2xl shadow-blue-900/5 overflow-hidden transition-all duration-300 transform group-hover:-translate-y-2 group-hover:shadow-blue-900/10">

                    {/* Background Pattern */}
                    <div className="absolute inset-0 opacity-[0.03]" style={{backgroundImage: 'radial-gradient(#4f46e5 1px, transparent 1px)', backgroundSize: '24px 24px'}}></div>
                    <div className="absolute top-0 w-full h-1/2 bg-gradient-to-b from-blue-50/50 to-transparent pointer-events-none"></div>

                    <div className="flex flex-col items-center justify-center z-10 p-8 text-center space-y-8">
                        <div className="relative">
                             <div className="absolute inset-0 bg-blue-400 rounded-full blur-xl opacity-20 animate-pulse"></div>
                             <div className="w-24 h-24 bg-gradient-to-br from-white to-blue-50 border border-white shadow-xl shadow-blue-500/10 text-blue-600 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform duration-500 relative z-10">
                                <span className="material-icons-round text-5xl bg-gradient-to-br from-blue-600 to-indigo-600 bg-clip-text text-transparent">add_a_photo</span>
                             </div>
                        </div>

                        <div className="space-y-2">
                            <h3 className="text-2xl font-black text-gray-900 tracking-tight">Escanear Plato</h3>
                            <p className="text-sm text-gray-500 font-medium px-6 leading-relaxed">
                                Sube una foto o captura tu comida para comenzar el análisis.
                            </p>
                        </div>

                        <div className="px-8 py-3 bg-gray-900 text-white text-sm font-bold rounded-full shadow-lg shadow-gray-900/20 group-hover:bg-blue-600 group-hover:shadow-blue-600/30 transition-all duration-300">
                            Comenzar Ahora
                        </div>
                    </div>

                    <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} />
                </label>
            </div>

            {/* Social Proof / Features */}
            <div className="w-full max-w-sm pt-2">
                <div className="grid grid-cols-3 gap-3">
                    {[
                        { icon: 'speed', label: 'Rápido', sub: '1s' },
                        { icon: 'verified', label: 'Preciso', sub: '99%' },
                        { icon: 'lock', label: 'Privado', sub: '100%' }
                    ].map((feat, i) => (
                        <div key={i} className="flex flex-col items-center justify-center p-4 bg-white/60 backdrop-blur-md border border-gray-100 rounded-2xl shadow-sm hover:bg-white transition-colors">
                            <span className="material-icons-round text-gray-400 text-xl mb-1">{feat.icon}</span>
                            <span className="font-bold text-gray-800 text-sm">{feat.label}</span>
                            <span className="text-[10px] text-gray-400 font-medium">{feat.sub}</span>
                        </div>
                    ))}
                </div>
            </div>
          </div>
        )}

        {view === AppView.HISTORY && (
            <div className="pt-6 animate-fade-in-up space-y-6 pb-24">
                <div className="flex items-center justify-between px-2">
                    <h2 className="text-3xl font-black text-gray-900 tracking-tight">Historial</h2>
                    <button onClick={resetApp} className="text-sm font-bold text-blue-600 hover:underline">
                        Nuevo Escaneo
                    </button>
                </div>

                <div className="space-y-4">
                    {history.length === 0 ? (
                        <div className="text-center py-20 flex flex-col items-center justify-center text-gray-400">
                            <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                                <span className="material-icons-round text-4xl text-gray-300">history_toggle_off</span>
                            </div>
                            <p className="font-medium">No hay análisis guardados aún.</p>
                            <p className="text-xs mt-2 opacity-70">Tus escaneos aparecerán aquí.</p>
                        </div>
                    ) : (
                        history.map((item) => (
                            <div 
                                key={item.id} 
                                onClick={() => loadHistoryItem(item)}
                                className="bg-white p-5 rounded-[1.5rem] shadow-sm border border-gray-100 hover:shadow-md hover:border-blue-100 transition-all cursor-pointer group flex items-center gap-5"
                            >
                                <div className="w-16 h-16 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl flex flex-col items-center justify-center border border-indigo-100/50 shrink-0">
                                    <span className="text-xl font-black text-indigo-600">{item.analysis.calories}</span>
                                    <span className="text-[10px] font-bold text-indigo-400 uppercase">Kcal</span>
                                </div>

                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">
                                            {formatDate(item.timestamp)}
                                        </span>
                                    </div>
                                    <p className="text-sm text-gray-600 font-medium truncate">
                                        {item.analysis.ingredients.slice(0, 3).join(', ')}...
                                    </p>
                                    <div className="flex gap-3 mt-2">
                                        {[
                                            { l: 'P', v: item.analysis.macros.protein, c: 'text-blue-500' },
                                            { l: 'C', v: item.analysis.macros.carbs, c: 'text-purple-500' },
                                            { l: 'G', v: item.analysis.macros.fat, c: 'text-emerald-500' }
                                        ].map((m, i) => (
                                            <span key={i} className={`text-xs font-bold ${m.c} bg-gray-50 px-1.5 py-0.5 rounded-md`}>
                                                {m.l}: {m.v}g
                                            </span>
                                        ))}
                                    </div>
                                </div>

                                <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center group-hover:bg-blue-600 group-hover:text-white transition-colors">
                                    <span className="material-icons-round text-lg">chevron_right</span>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        )}

        {view === AppView.ANALYSIS && (
          <div className="pb-24 space-y-6 animate-fade-in-up">
            {/* Image Preview Card */}
            <div className="bg-white p-3 rounded-[2rem] shadow-xl shadow-blue-900/5 border border-gray-100 relative overflow-hidden group">
                <div className="aspect-video w-full rounded-[1.5rem] overflow-hidden bg-gray-50 relative flex items-center justify-center">
                    {imageSrc ? (
                        <img 
                            src={imageSrc} 
                            alt="Uploaded food" 
                            className="w-full h-full object-cover"
                        />
                    ) : (
                        <div className="flex flex-col items-center text-gray-400">
                             <span className="material-icons-round text-4xl mb-2 opacity-50">image_not_supported</span>
                             <span className="text-xs font-bold uppercase tracking-wider opacity-60">Imagen no disponible</span>
                        </div>
                    )}
                    {/* Floating Back Button */}
                    <button 
                        onClick={() => setView(AppView.HOME)} // Use simple reset/back logic
                        className="absolute top-4 left-4 w-10 h-10 bg-white/20 backdrop-blur-lg border border-white/30 rounded-full flex items-center justify-center text-white hover:bg-white/40 transition-all shadow-lg"
                    >
                        <span className="material-icons-round">arrow_back</span>
                    </button>
                </div>
            </div>

            {loading && (
                <div className="bg-white/80 backdrop-blur-xl p-10 rounded-[2rem] shadow-xl border border-white text-center space-y-6 animate-pulse">
                    <div className="relative w-20 h-20 mx-auto">
                        <div className="absolute inset-0 border-4 border-gray-100 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                        <span className="material-icons-round absolute inset-0 flex items-center justify-center text-blue-600 text-2xl animate-pulse">restaurant</span>
                    </div>
                    <div>
                        <h3 className="text-2xl font-bold text-gray-900">Analizando...</h3>
                        <p className="text-gray-500 mt-2">Nuestra IA está identificando ingredientes y calculando macros.</p>
                    </div>
                </div>
            )}

            {error && !loading && (
                <div className="bg-red-50 p-8 rounded-[2rem] border border-red-100 text-center text-red-600">
                    <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <span className="material-icons-round text-3xl">error_outline</span>
                    </div>
                    <p className="font-medium">{error}</p>
                    <button onClick={resetApp} className="mt-6 px-6 py-2 bg-red-600 text-white rounded-full text-sm font-bold shadow-lg shadow-red-600/30 hover:bg-red-700 transition-colors">Intentar de nuevo</button>
                </div>
            )}

            {analysis && !loading && (
                <div className="space-y-6">

                    {/* Main Stats Card */}
                    <div className="bg-white p-8 rounded-[2.5rem] shadow-xl shadow-indigo-900/5 border border-gray-100 relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-50 rounded-bl-[100px] -z-0 opacity-50"></div>

                        <div className="relative z-10">
                            <h2 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-8 text-center">Análisis Nutricional</h2>

                            <div className="flex flex-col items-center mb-8">
                                <div className="relative">
                                    <h3 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-br from-gray-900 via-blue-900 to-indigo-900 tracking-tighter">
                                        {analysis.calories}
                                    </h3>
                                    <span className="absolute -right-8 top-2 text-xl font-bold text-gray-400">kcal</span>
                                </div>
                                <span className="text-sm font-medium text-gray-400 mt-2 bg-gray-50 px-3 py-1 rounded-full">Estimado por porción</span>
                            </div>

                            <div className="mt-4">
                                <MacrosChart data={analysis.macros} />
                                <div className="grid grid-cols-3 gap-4 mt-8">
                                    {[
                                        { label: 'Proteína', val: analysis.macros.protein, color: 'bg-blue-500', bg: 'bg-blue-50' },
                                        { label: 'Carbos', val: analysis.macros.carbs, color: 'bg-purple-500', bg: 'bg-purple-50' },
                                        { label: 'Grasa', val: analysis.macros.fat, color: 'bg-emerald-500', bg: 'bg-emerald-50' }
                                    ].map((macro, idx) => (
                                        <div key={idx} className={`flex flex-col items-center p-4 ${macro.bg} rounded-2xl border border-white shadow-sm`}>
                                            <div className={`w-2 h-2 ${macro.color} rounded-full mb-2`}></div>
                                            <span className="text-xl font-black text-gray-800">{macro.val}g</span>
                                            <span className="text-[10px] font-bold uppercase text-gray-400 mt-1">{macro.label}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Ingredients & Healthy Swaps */}
                    <div className="grid md:grid-cols-2 gap-4">
                        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
                            <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2 text-lg">
                                <span className="w-8 h-8 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center">
                                    <span className="material-icons-round text-sm">restaurant</span>
                                </span>
                                Ingredientes
                            </h3>
                            <div className="flex flex-wrap gap-2">
                                {analysis.ingredients.map((ing, idx) => (
                                    <span key={idx} className="bg-gray-50 text-gray-600 border border-gray-100 px-3 py-1.5 rounded-xl text-sm font-medium">
                                        {ing}
                                    </span>
                                ))}
                            </div>
                        </div>

                        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
                             <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2 text-lg">
                                <span className="w-8 h-8 rounded-full bg-green-100 text-green-600 flex items-center justify-center">
                                    <span className="material-icons-round text-sm">eco</span>
                                </span>
                                Mejoras
                            </h3>
                            <ul className="space-y-3">
                                {analysis.healthySwaps.map((swap, idx) => (
                                    <li key={idx} className="flex items-start gap-3 text-sm text-gray-600 bg-green-50/50 p-3 rounded-xl border border-green-100/50">
                                        <span className="material-icons-round text-green-500 text-base mt-0.5 shrink-0">check_circle</span>
                                        <span className="font-medium">{swap}</span>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>

                    {/* Alternative Recipes */}
                    <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] shadow-lg text-white relative overflow-hidden">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>

                        <h3 className="font-bold text-white mb-6 flex items-center gap-3 text-xl relative z-10">
                            <span className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center border border-white/10">
                                <span className="material-icons-round">auto_fix_high</span>
                            </span>
                            Versiones Ligeras
                        </h3>
                        <p className="text-blue-100/80 text-sm mb-6 relative z-10">
                            Toca una tarjeta para ver la receta completa.
                        </p>

                        <div className="space-y-4 relative z-10">
                            {analysis.healthierRecipes.map((recipe, idx) => (
                                <button 
                                    key={idx} 
                                    onClick={() => setSelectedRecipe(recipe)}
                                    className="w-full text-left flex justify-between items-center p-4 bg-white/10 backdrop-blur-md rounded-2xl border border-white/10 hover:bg-white/20 transition-all transform hover:scale-[1.02] active:scale-[0.98] group"
                                >
                                    <div>
                                        <h4 className="font-bold text-white text-lg flex items-center gap-2">
                                            {recipe.name}
                                            <span className="material-icons-round text-base opacity-0 group-hover:opacity-100 transition-opacity">open_in_new</span>
                                        </h4>
                                        <p className="text-xs text-blue-100/80 mt-1 line-clamp-1 font-medium">{recipe.description}</p>
                                    </div>
                                    <div className="bg-white/20 px-3 py-1.5 rounded-lg ml-4 shrink-0">
                                        <span className="text-sm font-bold text-white">{recipe.calories} kcal</span>
                                    </div>
                                </button>
                            ))}
                        </div>
                    </div>

                </div>
            )}
          </div>
        )}
      </main>

      {/* Recipe Detail Modal */}
      {selectedRecipe && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 animate-fade-in-up">
            {/* Backdrop */}
            <div 
                className="absolute inset-0 bg-gray-900/60 backdrop-blur-md transition-opacity" 
                onClick={() => setSelectedRecipe(null)}
            ></div>

            {/* Modal Card */}
            <div className="bg-white rounded-[2rem] w-full max-w-lg max-h-[85vh] overflow-y-auto relative shadow-2xl overflow-hidden flex flex-col">

                {/* Header */}
                <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 sm:p-8 text-white relative shrink-0">
                    <button 
                        onClick={() => setSelectedRecipe(null)}
                        className="absolute top-4 right-4 w-10 h-10 bg-black/10 hover:bg-black/20 rounded-full flex items-center justify-center text-white transition-colors"
                    >
                        <span className="material-icons-round">close</span>
                    </button>
                    <div className="mt-2">
                        <div className="inline-block px-3 py-1 bg-white/20 backdrop-blur-sm rounded-lg text-xs font-bold mb-3 border border-white/10">
                            {selectedRecipe.calories} CALORÍAS
                        </div>
                        <h2 className="text-2xl sm:text-3xl font-black tracking-tight leading-tight">
