## components/PieChart.tsx

Fix Recharts dimension warning by simplifying container styles and handling empty data cases safely.

```tsx
import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { MacroData } from '../types';

interface Props {
  data: MacroData;
}

const COLORS = ['#3b82f6', '#8b5cf6', '#10b981']; // Blue, Purple, Emerald

const MacrosChart: React.FC<Props> = ({ data }) => {
  const chartData = [
    { name: 'Proteína', value: data.protein },
    { name: 'Carbos', value: data.carbs },
    { name: 'Grasa', value: data.fat },
  ];

  // Prevent rendering if no data to avoid calculation errors
  const hasData = chartData.some(d => d.value > 0);

  if (!hasData) {
      return (
          <div className="w-full h-48 flex items-center justify-center bg-gray-50 rounded-2xl border border-gray-100 border-dashed">
              <span className="text-gray-400 text-xs font-medium">Sin datos</span>
          </div>
      );
  }

  return (
    <div className="w-full h-48 relative">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={chartData}
            cx="50%"
            cy="50%"
            innerRadius={60}
            outerRadius={80}
            paddingAngle={5}
            dataKey="value"
            stroke="none"
          >
            {chartData.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
            ))}
          </Pie>
          <Tooltip 
            contentStyle={{ 
                borderRadius: '16px', 
                border: 'none', 
                boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                padding: '8px 12px',
                fontSize: '12px',
                fontWeight: 600
            }}
            cursor={false}
          />
        </PieChart>
      </ResponsiveContainer>

      {/* Center Text */}
      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
         <span className="text-xs text-gray-400 font-bold uppercase tracking-wider">Macros</span>
      </div>
    </div>
  );
};

export default MacrosChart;
